"""Scoped drawing, layout and document history adapters reuse native read models."""
from backend.canvas.canvas_layout import layout_preview
from backend.editor.node.wireframe_context import wireframe_context
from backend.editor.node.node_links import NodeLinks
from backend.editor.node.node_journal import NodeJournal
from backend.editor.canvas_versions.canvas_versions import CanvasVersions
from backend.brain_opora.canvas_capabilities.contracts import contract

CONTRACTS = {
    "canvas_routes.preview_layout": contract(optional=("layer",), output="svg generated by native layout preview"),
    "canvas_routes.drawing": contract(optional=("layer",), output="Native drawing scene and revision"),
    "canvas_routes.drawing_files": contract(optional=("ids",), output="Native scoped drawing asset list"),
    "canvas_routes.wireframe_context_api": contract(optional=("layer",), output="Native drawing semantic context"),
    "canvas_routes.removal_preview": contract(("kind", "target"), output="Native removal impact; no removal"),
    "node_routes.node_links": contract(("node",), output="Scoped incoming/outgoing document links"),
    "node_routes.node_journal": contract(("node", "day"), output="Native journal revision and text"),
    "canvas_version_routes.canvas_versions": contract(optional=("versionId",), output="Native version listing or complete stored snapshot"),
    "canvas_version_routes.canvas_versions_head": contract(output="currentToken,dirty"),
}


def read(service, project, workspace, name, data):
    if name == "canvas_routes.preview_layout":
        return {"svg": layout_preview(service.view(project, workspace)["graph"], data.get("layer", ""))}
    if name == "canvas_routes.drawing":
        return service.drawing(project, workspace, data.get("layer", ""))
    if name == "canvas_routes.drawing_files":
        return service.drawing_file_list(project, workspace, data.get("ids", ""))
    if name == "canvas_routes.wireframe_context_api":
        layer = data.get("layer", "")
        return wireframe_context(project, workspace, layer, service.drawing(project, workspace, layer))
    if name == "canvas_routes.removal_preview":
        return service.removals.preview(project, workspace, data["kind"], data["target"])
    if name == "node_routes.node_links":
        return NodeLinks(service).links(project, workspace, data["node"])
    if name == "node_routes.node_journal":
        return NodeJournal(service).access(project, workspace, data["node"], data["day"])
    versions = CanvasVersions(service, getattr(service, "desktop_v3_state", None))
    if name == "canvas_version_routes.canvas_versions":
        return versions.read(project, workspace, data["versionId"]) if data.get("versionId") else versions.list(project, workspace)
    if name == "canvas_version_routes.canvas_versions_head":
        return versions.head(project, workspace)
    raise RuntimeError("No drawing/history read adapter.")
